        quantile(0.95)(tcp_fin_bytes) AS tcp_fin_p95_bytes,
        quantile(0.95)(tcp_fin_packets) AS tcp_fin_p95_packets,
        quantile(0.95)(tcp_fin_flows) AS tcp_fin_p95_flows,
        max(tcp_fin_bytes) AS tcp_fin_max_bytes,
        max(tcp_fin_packets) AS tcp_fin_max_packets,
        max(tcp_fin_flows) AS tcp_fin_max_flows,
        quantile(0.95)(tcp_syn_bytes) AS tcp_syn_p95_bytes,
        quantile(0.95)(tcp_syn_packets) AS tcp_syn_p95_packets,
        quantile(0.95)(tcp_syn_flows) AS tcp_syn_p95_flows,
        max(tcp_syn_bytes) AS tcp_syn_max_bytes,
        max(tcp_syn_packets) AS tcp_syn_max_packets,
        max(tcp_syn_flows) AS tcp_syn_max_flows,
        quantile(0.95)(tcp_rst_bytes) AS tcp_rst_p95_bytes,
        quantile(0.95)(tcp_rst_packets) AS tcp_rst_p95_packets,
        quantile(0.95)(tcp_rst_flows) AS tcp_rst_p95_flows,
