        quantile(0.95)(tcp_psh_bytes) AS tcp_psh_p95_bytes,
        quantile(0.95)(tcp_psh_packets) AS tcp_psh_p95_packets,
        quantile(0.95)(tcp_psh_flows) AS tcp_psh_p95_flows,
