        quantile(0.95)(tcp_ack_flows) AS tcp_ack_p95_flows,
        max(tcp_ack_bytes) AS tcp_ack_max_bytes,
        max(tcp_ack_packets) AS tcp_ack_max_packets,
        max(tcp_ack_flows) AS tcp_ack_max_flows,
        quantile(0.95)(tcp_urg_bytes) AS tcp_urg_p95_bytes,
        quantile(0.95)(tcp_urg_packets) AS tcp_urg_p95_packets,
        quantile(0.95)(tcp_urg_flows) AS tcp_urg_p95_flows,
        max(tcp_urg_bytes) AS tcp_urg_max_bytes,
        max(tcp_urg_packets) AS tcp_urg_max_packets,
        max(tcp_urg_flows) AS tcp_urg_max_flows,
            sum(any_bytes) AS total_bytes
        FROM flows.prefixes_ip_port_1h
        WHERE time_received >= NOW() - INTERVAL 1 DAY
        GROUP BY prefix, dst_addr, dst_port, time_received
    )
    SELECT * EXCEPT total_bytes
    FROM stats
    QUALIFY total_bytes >= quantile(0.05)(total_bytes) OVER (PARTITION BY prefix, dst_addr);

